package com.bank.training.service;

import com.bank.training.model.Employee;
import java.util.List;
import java.util.Set;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class TrainingService {
    private static final Logger log = Logger.getLogger(TrainingService.class.getName());
    // Built once; HashSet → average O(1) contains.
    private static final Set<String> EXCLUDED = Set.of("IT", "HR");

    public List<Employee> eligibleForFieldTraining(List<Employee> employees) {
        log.info(() -> "Excluding departments " + EXCLUDED + " from field training");
        return employees.stream()
                // Keep only employees whose department is NOT in the excluded set.
                .filter(e -> !EXCLUDED.contains(e.getDepartment()))
                .collect(Collectors.toList());
    }
}
