package com.bank.training;

import com.bank.training.model.Employee;
import com.bank.training.service.TrainingService;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT"),
            new Employee("Priya",  "Sales"),
            new Employee("Amit",   "HR"),
            new Employee("Neha",   "Marketing"),
            new Employee("Karan",  "Sales")
        );

        new TrainingService().eligibleForFieldTraining(staff)
            .forEach(e -> log.info(() -> "Field-training eligible: " + e));
    }
}
